  }
}

query GetAgentOrgDefinitions {
  agentOrgDefinitions {
    id
    name
    description
    instructions
    category
    avatarUrl
    revision
    handoffs {
      from
      to
      rules
      __typename
    }
    members {
      memberName
      ref
      refType
      refScope
      __typename
    }
    defaultLaunchConfig {
      llmModelIdentifier
      runtimeKind
      llmConfig
      __typename
    }
    __typename
  }
}

query GetApplicationsCapability {
  applicationsCapability {
    ...ApplicationsCapabilityFields
    __typename
  }
}

fragment ApplicationsCapabilityFields on ApplicationsCapability {
  enabled
  scope
  settingKey
  source
  __typename
}

